mapper.select:
SELECT #{start} time,proto_type type,SUM(c2s_byte_len)+SUM(s2c_byte_len) count
FROM traffic_protocol_statistic
   WHERE stat_time >= #{start}
      AND stat_time < #{end}
GROUP BY proto_type;

select #{start} time,proto_type type,max(link_num) linknum ,sum(c2s_pkt_num)+sum(s2c_pkt_num) pakeagenum,
sum(c2s_byte_len)+sum(s2c_byte_len) bytes
FROM traffic_protocol_statistic
  WHERE stat_time >= #{start}
  AND stat_time < #{end}
GROUP BY proto_type

SELECT stat_time time ,ip_addr ip,area_id area,link_num links,c2s_pkt_num+s2c_pkt_num packets,
 c2s_byte_len+s2c_byte_len bytes
 FROM traffic_ip_active_statistic
 WHERE stat_time >= #{start}
       AND stat_time < #{end}
